<?php
$q = fn(string $f, string $t) => url('/admin/reports') . '?from=' . $f . '&to=' . $t;
$today = date('Y-m-d'); $max = max(1, ...array_map(fn($s) => $s['t'], $series ?: [['t' => 1]])); $n = max(1, count($series));
$presets = ['Today' => [$today, $today], 'Last 7 days' => [date('Y-m-d', strtotime('-6 days')), $today], 'Last 30 days' => [date('Y-m-d', strtotime('-29 days')), $today], 'This month' => [date('Y-m-01'), $today], 'Last month' => [date('Y-m-01', strtotime('first day of last month')), date('Y-m-t', strtotime('last month'))]];
$labels = ['placed' => 'Placed', 'confirmed' => 'Confirmed', 'processing' => 'Processing', 'packed' => 'Packed', 'shipped' => 'Shipped', 'delivered' => 'Delivered', 'cancelled' => 'Cancelled', 'cart' => 'Cart', 'quick_order' => 'Quick Order', 'voice_order' => 'Voice Order'];
$bar = function (array $rows, string $key, string $val) { $m = max(1, ...array_map(fn($r) => (float)$r[$val], $rows ?: [[$val => 1]])); foreach ($rows as $r): $w = round((float)$r[$val] / $m * 100); ?>
  <div class="py-1.5"><div class="flex justify-between text-sm gap-2"><span class="truncate"><?= e($GLOBALS['labels'][$r[$key]] ?? $r[$key]) ?></span><b class="shrink-0"><?= money($r[$val]) ?></b></div><div class="h-1.5 rounded-full bg-black/5 mt-1"><div class="h-1.5 rounded-full" style="width:<?= $w ?>%;background:linear-gradient(90deg,var(--c-primary),var(--c-accent))"></div></div></div>
<?php endforeach; }; $GLOBALS['labels'] = $labels; ?>
<div class="flex flex-wrap items-end justify-between gap-3 mb-5">
  <div><h2 class="font-display font-bold text-2xl">Sales Reports</h2><p class="text-sm muted">Cancelled orders are not counted in revenue.</p></div>
  <div class="flex flex-wrap gap-2"><a class="btn btn-outline btn-sm" href="<?= e(url('/admin/reports/export') . '?what=daily&from=' . $from . '&to=' . $to) ?>"><?= icon('download', 'w-4 h-4') ?> Daily CSV</a><a class="btn btn-outline btn-sm" href="<?= e(url('/admin/reports/export') . '?what=products&from=' . $from . '&to=' . $to) ?>"><?= icon('download', 'w-4 h-4') ?> Products CSV</a><button class="btn btn-primary btn-sm" onclick="print()"><?= icon('printer', 'w-4 h-4') ?> Print</button></div>
</div>
<form method="get" class="card p-4 flex flex-wrap items-end gap-3 mb-5"><div><label class="label" for="from">From</label><input id="from" type="date" name="from" value="<?= e($from) ?>" class="input !w-auto" max="<?= $today ?>"></div><div><label class="label" for="to">To</label><input id="to" type="date" name="to" value="<?= e($to) ?>" class="input !w-auto" max="<?= $today ?>"></div><button class="btn btn-primary">Apply</button>
  <div class="flex flex-wrap gap-1.5 ml-auto"><?php foreach ($presets as $l => [$f, $t]): ?><a class="chip !py-1.5 <?= $f === $from && $t === $to ? 'active' : '' ?>" href="<?= e($q($f, $t)) ?>"><?= e($l) ?></a><?php endforeach; ?></div></form>

<div class="grid grid-cols-2 xl:grid-cols-4 gap-3 mb-5">
  <?php foreach ([['Revenue', money($tot['revenue']), 'indian-rupee', 'var(--c-primary)'], ['Orders', (int)$tot['orders'], 'receipt', 'var(--c-secondary)'], ['Avg. order value', money($tot['avg_order']), 'trending-up', '#12b76a'], ['Units sold', number_format($items), 'package', 'var(--c-accent)'], ['Paid', money($tot['paid']), 'badge-check', '#12b76a'], ['Payment pending', money($tot['pending']), 'hourglass', '#f79009'], ['Discounts given', money($tot['discount']), 'badge-percent', 'var(--c-secondary)'], ['Cancelled orders', $cancelled, 'ban', '#f04438']] as [$l, $v, $ic, $c]): ?>
  <div class="card p-4 flex items-center gap-3"><span class="w-11 h-11 rounded-xl flex items-center justify-center text-white shrink-0" style="background:<?= $c ?>"><?= icon($ic, 'w-5 h-5') ?></span><div class="min-w-0"><div class="text-xs muted"><?= e($l) ?></div><div class="font-display font-bold text-lg truncate"><?= is_string($v) ? $v : (int)$v ?></div></div></div>
  <?php endforeach; ?>
</div>

<div class="card p-5 mb-5"><div class="flex items-center justify-between mb-3"><h3 class="font-bold">Revenue by day</h3><span class="text-xs muted"><?= e(date('d M', strtotime($from))) ?> – <?= e(date('d M Y', strtotime($to))) ?></span></div>
  <div class="overflow-x-auto"><svg viewBox="0 0 <?= max(720, $n * 18) ?> 220" class="w-full min-w-[640px] h-56" role="img" aria-label="Revenue per day chart" preserveAspectRatio="none">
    <?php $W = max(720, $n * 18); $bw = $W / $n; foreach ($series as $i => $s): $h = $s['t'] > 0 ? max(3, $s['t'] / $max * 170) : 0; ?>
      <g><title><?= e(date('d M', strtotime($s['d']))) ?>: <?= e(money($s['t'])) ?> (<?= (int)$s['c'] ?> orders)</title><rect x="<?= round($i * $bw + $bw * .15, 1) ?>" y="<?= round(190 - $h, 1) ?>" width="<?= round($bw * .7, 1) ?>" height="<?= round($h, 1) ?>" rx="3" fill="var(--c-primary)" opacity=".9"/></g>
      <?php if ($n <= 31 || $i % ceil($n / 24) === 0): ?><text x="<?= round($i * $bw + $bw / 2, 1) ?>" y="210" text-anchor="middle" font-size="10" fill="currentColor" opacity=".55"><?= e(date('d', strtotime($s['d']))) ?></text><?php endif; ?>
    <?php endforeach; ?><line x1="0" x2="<?= $W ?>" y1="190" y2="190" stroke="currentColor" opacity=".12"/></svg></div></div>

<div class="grid lg:grid-cols-2 gap-5">
  <div class="card p-5"><h3 class="font-bold mb-2">Top products</h3><?php if (!$top): ?><p class="text-sm muted py-4">No sales in this period.</p><?php else: ?><div class="overflow-x-auto"><table class="table-x w-full text-sm"><thead><tr><th>Product</th><th class="text-right">Units</th><th class="text-right">Revenue</th></tr></thead><tbody><?php foreach ($top as $r): ?><tr><td><b><?= e($r['name']) ?></b><div class="text-xs muted font-mono"><?= e($r['sku']) ?></div></td><td class="text-right"><?= (int)$r['q'] ?></td><td class="text-right font-semibold"><?= money($r['t']) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></div>
  <div class="card p-5"><h3 class="font-bold mb-2">Sales by category</h3><?php if (!$cats): ?><p class="text-sm muted py-4">No data.</p><?php else: $bar($cats, 'k', 't'); endif; ?></div>
  <div class="card p-5"><h3 class="font-bold mb-2">Orders by status</h3><?php foreach ($status as $r): ?><div class="flex justify-between py-2 border-b border-black/5 last:border-0 text-sm"><span><?= e($labels[$r['k']] ?? $r['k']) ?></span><span><b><?= (int)$r['c'] ?></b> <span class="muted">· <?= money($r['t']) ?></span></span></div><?php endforeach; if (!$status): ?><p class="text-sm muted py-4">No orders.</p><?php endif; ?></div>
  <div class="card p-5"><h3 class="font-bold mb-2">Order channel &amp; payment</h3><div class="text-xs muted mb-1">Channel</div><?php $bar($source, 'k', 't'); ?><div class="text-xs muted mt-3 mb-1">Payment method</div><?php foreach ($payment as $r): ?><div class="flex justify-between text-sm py-1"><span class="uppercase"><?= e($r['k']) ?></span><span><b><?= (int)$r['c'] ?></b> <span class="muted">· <?= money($r['t']) ?></span></span></div><?php endforeach; ?></div>
  <div class="card p-5"><h3 class="font-bold mb-2">Top locations</h3><?php foreach ($places as $r): ?><div class="flex justify-between py-2 border-b border-black/5 last:border-0 text-sm"><span><?= e($r['city']) ?>, <span class="muted"><?= e($r['state']) ?></span></span><span><b><?= (int)$r['c'] ?></b> <span class="muted">· <?= money($r['t']) ?></span></span></div><?php endforeach; if (!$places): ?><p class="text-sm muted py-4">No data.</p><?php endif; ?></div>
  <div class="card p-5"><h3 class="font-bold mb-2">Best customers</h3><?php foreach ($customers as $r): ?><div class="flex justify-between py-2 border-b border-black/5 last:border-0 text-sm"><span><?= e($r['customer_name']) ?> <span class="muted font-mono text-xs"><?= e($r['mobile']) ?></span></span><span><b><?= (int)$r['c'] ?></b> <span class="muted">· <?= money($r['t']) ?></span></span></div><?php endforeach; if (!$customers): ?><p class="text-sm muted py-4">No data.</p><?php endif; ?></div>
  <div class="card p-5 lg:col-span-2"><h3 class="font-bold mb-2 flex items-center gap-2"><?= icon('alert-triangle', 'w-4 h-4 text-amber-500') ?> Low stock (needs restocking)</h3><?php if (!$lowStock): ?><p class="text-sm muted py-2">All products are well stocked. 🎉</p><?php else: ?><div class="grid sm:grid-cols-2 gap-x-6"><?php foreach ($lowStock as $r): ?><a href="<?= e(url('/admin/products/' . (int)$r['id'] . '/edit')) ?>" class="flex justify-between py-2 border-b border-black/5 text-sm hover:text-primary"><span class="truncate"><?= e($r['name']) ?> <span class="muted font-mono text-xs"><?= e($r['sku']) ?></span></span><b class="<?= (int)$r['stock'] === 0 ? 'text-red-600' : 'text-amber-600' ?>"><?= (int)$r['stock'] ?> left</b></a><?php endforeach; ?></div><?php endif; ?></div>
</div>
